 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # A template may be shown as a straight run along an edge (as in the
    # test), or as a connected colored component inside the grid (demo).
    edge_candidates = []
    for c in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][c] == background:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != background:
                r += 1
            if r - start >= 2:
                edge_candidates.append((r - start, [(rr, c, grid[rr][c]) for rr in range(start, r)]))
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == background:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != background:
                c += 1
            if c - start >= 2:
                edge_candidates.append((c - start, [(r, cc, grid[r][cc]) for cc in range(start, c)]))

    if edge_candidates:
        template = max(edge_candidates, key=lambda item: item[0])[1]
    else:
        seen = set()
        components = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] == background or (r, c) in seen:
                    continue
                q = deque([(r, c)])
                seen.add((r, c))
                comp = []
                while q:
                    rr, cc = q.popleft()
                    comp.append((rr, cc, grid[rr][cc]))
                    for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                        if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] != background:
                            seen.add((nr, nc))
                            q.append((nr, nc))
                components.append(comp)
        template = max(components, key=len)

    # The template is a straight sequence; its middle cell is the anchor.
    rows = [p[0] for p in template]
    cols = [p[1] for p in template]
    if len(set(rows)) == 1:
        template.sort(key=lambda p: p[1])
        anchor_index = len(template) // 2
        drdc = [(0, i - anchor_index, color) for i, (_, _, color) in enumerate(template)]
    else:
        template.sort(key=lambda p: p[0])
        anchor_index = len(template) // 2
        drdc = [(i - anchor_index, 0, color) for i, (_, _, color) in enumerate(template)]

    template_positions = {(r, c) for r, c, _ in template}
    target_counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                            if grid[r][c] != background and (r, c) not in template_positions)
    target = target_counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == target and (r, c) not in template_positions:
                for dr, dc, color in drdc:
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
    return out


